/**
 * @file report.ts
 * @brief Type definitions representing the avero.report/v1 contract schema.
 * @details Strictly mirrors the deterministic report JSON generated by the Avero core engine.
 */

/**
 * @brief Severity level of a finding.
 */
export type Severity = "critical" | "high" | "medium" | "low" | "info";

/**
 * @brief Tool metadata identifying the generator.
 */
export interface ToolMeta {
  name: string;
  version: string;
  ir_version: string;
}

/**
 * @brief Cryptographic hash digest mapping.
 */
export interface Hashes {
  md5?: string;
  sha1?: string;
  sha256: string;
  [key: string]: string | undefined;
}

/**
 * @brief Binary section information.
 */
export interface Section {
  name: string;
  va: number;
  vsize: number;
  raw_offset: number;
  raw_size: number;
  entropy: number;
  flags: string[];
}

/**
 * @brief Imported symbol or function.
 */
export interface ImportEntry {
  library: string;
  name?: string;
  ordinal?: number;
  iat_rva?: number;
}

/**
 * @brief Exported symbol or function.
 */
export interface ExportEntry {
  name?: string;
  ordinal: number;
  rva: number;
  forwarder?: string;
}

/**
 * @brief Extracted string entry with encoding.
 */
export interface StringEntry {
  offset: number;
  value: string;
  encoding: "ascii" | "utf16le" | string;
  section?: string;
}

/**
 * @brief Producer engine identification.
 */
export interface Producer {
  engine: string;
  version: string;
}

/**
 * @brief Concrete evidence pointer grounding a finding.
 */
export interface Evidence {
  id: string;
  producer: Producer;
  kind: string;
  locator: Record<string, unknown>;
  excerpt: string;
  confidence: number;
  limitations?: string[];
}

/**
 * @brief Analyzed artifact summary and structural data.
 */
export interface Artifact {
  ir_version: string;
  id: string;
  path: string;
  size: number;
  kinds: string[];
  architecture?: string;
  bits?: number;
  endianness?: "little" | "big";
  entropy: number;
  hashes: Hashes;
  sections?: Section[];
  imports?: ImportEntry[];
  exports?: ExportEntry[];
  strings?: StringEntry[];
  metadata?: Record<string, unknown>;
  evidence?: Evidence[];
}

/**
 * @brief Observation or security finding linked to evidence.
 */
export interface Finding {
  id: string;
  severity: Severity;
  category: string;
  title: string;
  detail: string;
  evidence_ids: string[];
  confidence: number;
  remediation?: string;
}

/**
 * @brief Root Avero report structure (avero.report/v1).
 */
export interface AveroReport {
  schema_id: string;
  tool: ToolMeta;
  generated_at: string;
  artifact: Artifact;
  findings: Finding[];
  facts?: Record<string, unknown>;
  coverage?: Record<string, string>;
  unknowns?: string[];
  warnings?: string[];
}

/**
 * @brief Brief summary of a report for recent listings.
 */
export interface ReportSummary {
  id: string;
  name: string;
  sha256: string;
  size: number;
  kinds: string[];
  generated_at: string;
  findingsCount: {
    critical: number;
    high: number;
    medium: number;
    low: number;
    info: number;
    total: number;
  };
}
